Set tStatus = $$$OK
Try {
	If '$IsObject($get(pBatch)) Set tStatus = $$$ERROR($$$ObjectInstanceRequired) Quit
	If '$IsObject(pIOStream) {
		Set tFilename = pIOStream
		Set pIOStream = ##class(%IO.FileStream).%New()
		Do pIOStream.Open(tFilename,"WAE",,"UTF-8",.tStatus)
		If $$$ISERR(tStatus) Quit
	}
	If $IsObject(pBatch.RecordA) {
		Set tStatus = ##class(IHC.ITF.DStruc.ShKeyWordRecA).PutObject(pIOStream,pBatch.RecordA,0)
		If $$$ISERR(tStatus) Quit
	}
	If $IsObject(pBatch.RecordC) {
		Set tStatus = ##class(IHC.ITF.DStruc.ShKeyWordRecC837I).PutObject(pIOStream,pBatch.RecordC,0)
